#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
push_tg.py 部署包
=================
还原 TG 推送脚本到 v5scripts/，并创建 token 配置文件模板。
token 不写进本脚本，部署后单独填，避免进 git。
用法: python3 deploy_push_tg.py
"""
import base64, os
TARGET = "/root/bi_dashboard/v5scripts/push_tg.py"
BLOB = ""
with open(TARGET, 'wb') as f:
    f.write(base64.b64decode(BLOB))
print(f'  已写入 {TARGET}')

# 创建 token 配置文件（如果不存在）——单独存，不进 git
ENV_FILE = "/root/bi_dashboard/v5scripts/tg_config.sh"
if not os.path.exists(ENV_FILE):
    with open(ENV_FILE, 'w') as f:
        f.write("# Telegram 推送配置（本文件勿上传 git）\n")
        f.write("export TG_TOKEN=\"在这里填你的token\"\n")
        f.write("export TG_CHAT_ID=\"6304982727\"\n")
    os.chmod(ENV_FILE, 0o600)  # 仅 root 可读写
    print(f'  已创建 token 配置模板 {ENV_FILE}（权限600）')
    print(f'  ⚠️ 需手动填入 token')
else:
    print(f'  {ENV_FILE} 已存在，跳过')

print()
print('='*50)
print('✅ push_tg.py 部署完成')
print('   下一步：编辑 tg_config.sh 填入 token')
print('='*50)
